import { Link } from 'react-router-dom';

// การ์ดหนังสือ 1 ใบ
function BookCard({ book }) {
  const price = book.priceTHB ? `฿${book.priceTHB.toLocaleString('th-TH')}` : null;
  return (
    <Link to={`/books/${book.id}`}
          className="group block overflow-hidden rounded-xl border border-amber-100 bg-white transition hover:border-amber-300 hover:shadow-md">
      {book.coverUrl ? (
        <img src={book.coverUrl} alt={`ปกหนังสือ ${book.title}`} loading="lazy"
             className="aspect-[2/3] w-full object-cover" />
      ) : (
        <div className="grid aspect-[2/3] w-full place-items-center bg-amber-50 text-4xl">📖</div>
      )}
      <div className="p-3">
        <h3 className="truncate font-medium text-slate-900 text-sm" title={book.title}>{book.title}</h3>
        <p className="truncate text-xs text-slate-500 mt-0.5">{book.author}</p>
        <div className="mt-1 flex items-center justify-between">
          {book.category && (
            <span className="rounded-full bg-amber-50 px-2 py-0.5 text-xs text-amber-700">{book.category}</span>
          )}
          {price && <span className="text-xs font-medium text-slate-700">{price}</span>}
        </div>
      </div>
    </Link>
  );
}

export default BookCard;
